window.EP = {"name": "ch15", "label": "एपिसोड 15", "en": "Some Questions the Mountains Keep", "duration": 1333.98, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 14.8, "text": "चैप्टर फ़िफ़्टीन। सम क्वेश्चन्स द माउंटेन्स कीप"}, {"start": 15.35, "end": 18.21, "text": "डे फ़िफ़्टीन। खलिया एंड मुनस्यारी"}], "captions": [{"start": 19.76, "end": 20.56, "text": "हम भागे।", "who": "", "voice": "narrator", "diary": false}, {"start": 21.26, "end": 24.18, "text": "मैं इसे बहादुरी से बयान करना चाहूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 24.18, "end": 33.58, "text": "वो मैदानों से आया एक प्रोफ़ेसर था, खरोंचे हुए चेहरे वाली एक औरत, एक नोटबुक भींचे उसका भाई, गढ़वाली टोपी में एक ड्राइवर,", "who": "", "voice": "narrator", "diary": false}, {"start": 33.58, "end": 40.05, "text": "और थर्मल कैमरे वाला एक भूतपूर्व यूट्यूबर, पहली रोशनी में, साढ़े तीन हज़ार मीटर पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 40.05, "end": 42.89, "text": "एक जमे हुए बुग्याल के पार भागते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 42.89, "end": 45.82, "text": "टूटे हुए अकॉर्डियन की तरह हाँफते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 46.27, "end": 47.43, "text": "लेकिन हम भागे।", "who": "", "voice": "narrator", "diary": false}, {"start": 47.43, "end": 57.22, "text": "और हमारे पीछे, जंगल से ट्रेल पर ऊपर, एक स्थिर फ़ौजी चाल से, कमांडेंट धामी के दोनों ख़ामोश आदमी आ रहे थे, और उनके पीछे,", "who": "", "voice": "narrator", "diary": false}, {"start": 57.22, "end": 62.54, "text": "पंद्रह दिनों में पहली बार हमारी तरफ़, ख़ाकी में चार पुलिस अफ़सर,", "who": "", "voice": "narrator", "diary": false}, {"start": 62.54, "end": 65.86, "text": "ठंड में उनकी साँस धुएँ की तरह उड़ती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 66.31, "end": 73.43, "text": "झोपड़ी, बुग्याल के अपने उभार पर अकेली खड़ी थी: नीची, चौकोर, धूसर पत्थर की बनी,", "who": "", "voice": "narrator", "diary": false}, {"start": 73.43, "end": 76.17, "text": "उसकी स्लेट की छत आधी गिरी हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 76.17, "end": 80.18, "text": "लकड़ी का एक दरवाज़ा एक क़ब्ज़े से लटकता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 80.18, "end": 87.12, "text": "उसके आगे, ज़मीन नीली छाया की एक खाई में गिर जाती थी: गोरी गंगा की गहरी घाटी,", "who": "", "voice": "narrator", "diary": false}, {"start": 87.12, "end": 90.59, "text": "जोहार का पुराना रास्ता, राजुला का देश,", "who": "", "voice": "narrator", "diary": false}, {"start": 90.59, "end": 93.79, "text": "उत्तर में तिब्बत की तरफ़ घूमता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 93.79, "end": 99.08, "text": "और दुनिया के दूसरे छोर पर, सूर्योदय में सुनहरी, नंदा देवी।", "who": "", "voice": "narrator", "diary": false}, {"start": 99.53, "end": 102.37, "text": "कुंदन सिंह ने अपनी जगह अच्छी चुनी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 102.37, "end": 105.75, "text": "यहाँ से, उनकी देवी अपनी संपत्ति देख सकती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 106.2, "end": 108.85, "text": "रोहन के आदमी झोपड़ी के बाहर खड़े थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 108.85, "end": 110.84, "text": "उन्होंने पुलिस को आते देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 110.84, "end": 114.31, "text": "उन्होंने एक-दूसरे को देखा, और बिना एक शब्द कहे,", "who": "", "voice": "narrator", "diary": false}, {"start": 114.31, "end": 118.81, "text": "पाले से ढकी घास पर बैठ गए, और अपने हाथ अपने घुटनों पर रख लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 118.81, "end": 124.12, "text": "मैंने स्टूडेंट्स को इससे कम गरिमा के साथ इम्तिहान में हार मानते देखा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 124.82, "end": 126.1, "text": "दरवाज़ा खुला था।", "who": "", "voice": "narrator", "diary": false}, {"start": 126.8, "end": 128.93, "text": "रोहन अंदर था, कच्चे फ़र्श पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 128.93, "end": 132.24, "text": "लकड़ी के एक डब्बे के सामने घुटनों के बल बैठा।", "who": "", "voice": "narrator", "diary": false}, {"start": 132.69, "end": 134.67, "text": "वो कोई बड़ा डब्बा नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 134.67, "end": 139.02, "text": "पुरानी लकड़ी, उम्र और धुएँ से काली, एक छोटे सूटकेस जितनी,", "who": "", "voice": "narrator", "diary": false}, {"start": 139.02, "end": 141.53, "text": "लोहे के एक ज़ंग लगे कुंडे के साथ।", "who": "", "voice": "narrator", "diary": false}, {"start": 141.53, "end": 145.27, "text": "वो कोने में, तह किए हुए कंबलों के ढेर के नीचे था,", "who": "", "voice": "narrator", "diary": false}, {"start": 145.27, "end": 148.7, "text": "जहाँ कोई चरवाहा अपनी फ़ालतू चीज़ें रखता होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 148.7, "end": 150.53, "text": "रोहन ने उसे खोल लिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 150.98, "end": 153.76, "text": "अंदर, एक फीके कपड़े में लिपटा,", "who": "", "voice": "narrator", "diary": false}, {"start": 153.76, "end": 158.02, "text": "जो कभी लाल रहा होगा, धातु का एक टुकड़ा रखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 158.47, "end": 159.59, "text": "बस इतना ही था।", "who": "", "voice": "narrator", "diary": false}, {"start": 159.59, "end": 167.24, "text": "फीकी धूसर धातु का एक मुड़ा, ऐंठा हुआ ब्रैकेट, मेरी बाँह जितना लंबा, एक सिरे पर बोल्ट के दो छेद,", "who": "", "voice": "narrator", "diary": false}, {"start": 167.24, "end": 169.89, "text": "और दूसरे सिरे पर एक दाँतेदार टूट,", "who": "", "voice": "narrator", "diary": false}, {"start": 169.89, "end": 173.19, "text": "जैसे उसे किसी भारी चीज़ से उखाड़ा गया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 173.19, "end": 176.41, "text": "उसकी एक साइड पर, साठ साल की मैल के नीचे,", "who": "", "voice": "narrator", "diary": false}, {"start": 176.41, "end": 180.27, "text": "बस अंग्रेज़ी के कुछ स्टेंसिल किए अक्षर दिखते थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 180.27, "end": 182.84, "text": "एक शब्द पढ़ने के लिए काफ़ी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 182.84, "end": 184.61, "text": "ये जानने के लिए काफ़ी,", "who": "", "voice": "narrator", "diary": false}, {"start": 184.61, "end": 188.31, "text": "कि कुमाऊँ के किसी चरवाहे ने इसे नहीं बनाया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 188.76, "end": 192.91, "text": "रोहन के हाथ में एक छोटा, पीला डिवाइस था: एक रेडिएशन मीटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 192.91, "end": 197.56, "text": "वो उसे ब्रैकेट के ऊपर, बहुत पास, धीरे-धीरे ऊपर-नीचे घुमा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 198.26, "end": 199.61, "text": "वो ख़ामोश था।", "who": "", "voice": "narrator", "diary": false}, {"start": 200.31, "end": 202.31, "text": "उसने उसे फिर घुमाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 202.31, "end": 203.01, "text": "ख़ामोश।", "who": "", "voice": "narrator", "diary": false}, {"start": 203.01, "end": 206.4, "text": "उसने उसे धातु से बिल्कुल सटा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 206.4, "end": 207.1, "text": "ख़ामोश।", "who": "", "voice": "narrator", "diary": false}, {"start": 207.55, "end": 211.01, "text": "वो अपनी एड़ियों पर पीछे बैठ गया, और उसे देखने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 211.01, "end": 215.09, "text": "और दरवाज़े पर खड़े होकर, मैंने रोहन सहगल को समझते हुए देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 215.54, "end": 218.25, "text": "मेरे पीछे, क्षितिज ने धीरे से कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 218.25, "end": 221.04, "text": "उस तरह, जैसे कोई प्रार्थना करता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 221.24, "end": 223.92, "text": "जो गरम था, वो बर्फ़ ने लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 224.37, "end": 227.17, "text": "गौरव ने, उसके बग़ल में, उसे पूरा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 227.37, "end": 229.82, "text": "जो ठंडा बचा, चरवाहा ले चला।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 230.27, "end": 236.82, "text": "चरवाहों ने उसे उन्नीस सौ छियासठ के बसंत में पाया था: बर्फ़ में भाप छोड़ती कोई चीज़,", "who": "", "voice": "narrator", "diary": false}, {"start": 236.82, "end": 241.23, "text": "बड़े पहाड़ के पास, ऊपर, जहाँ कुछ भी गरम नहीं होना चाहिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 241.23, "end": 248.57, "text": "मुझे लगता है, उन्होंने ख़ुद डब्बा पाया था, पिघली हुई बर्फ़ की अपनी छोटी सी गुफा में धँसा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 248.57, "end": 253.61, "text": "उसी तरह, जैसे दूसरा डिवाइस दो साल बाद नंदा कोट पर मिलने वाला था।", "who": "", "voice": "narrator", "diary": false}, {"start": 253.61, "end": 260.55, "text": "और वो डर गए थे, उसी तरह, जैसे कोई भी समझदार इंसान, बर्फ़ में किसी ऐसी गरम चीज़ से डरेगा,", "who": "", "voice": "narrator", "diary": false}, {"start": 260.55, "end": 265.36, "text": "जिसे छूने से विदेशी पर्वतारोहियों ने पोर्टर्स को मना किया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 265.36, "end": 267.8, "text": "तो उन्होंने उसे वहीं छोड़ दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 267.8, "end": 272.93, "text": "उन्होंने उसका गरम दिल बर्फ़ के हवाले कर दिया, और बर्फ़ उसे ले गई,", "who": "", "voice": "narrator", "diary": false}, {"start": 272.93, "end": 277.81, "text": "गहरे, और गहरे, ठीक वैसे ही, जैसे दोरजे ने चंद्रशिला पर कहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 278.26, "end": 280.7, "text": "लेकिन एक टुकड़ा टूट गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 280.7, "end": 281.7, "text": "एक ब्रैकेट।", "who": "", "voice": "narrator", "diary": false}, {"start": 281.7, "end": 282.69, "text": "एक फ़िटिंग।", "who": "", "voice": "narrator", "diary": false}, {"start": 282.69, "end": 287.56, "text": "कुछ, जिसने डब्बे को जोड़े रखा था, या नीचे दबाए रखा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 287.56, "end": 290.54, "text": "वो टुकड़ा धूप में सतह पर पड़ा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 290.54, "end": 293.61, "text": "उस चीज़ से गरम, जिसे वो छू रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 293.61, "end": 301.65, "text": "और कुंदन सिंह, एक जवान चरवाहा, जो इस बात के सबूत के बिना नहीं जा सकता था, कि ये सब सच था,", "who": "", "voice": "narrator", "diary": false}, {"start": 301.65, "end": 305.08, "text": "उसे उठा लाया, शायद अपने हाथ जलाते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 305.08, "end": 308.51, "text": "उसे एक लाल कपड़े में लपेटा, और ले चला।", "who": "", "voice": "narrator", "diary": false}, {"start": 308.51, "end": 313.48, "text": "वो उसके हाथों में ठंडा हो गया, और फिर कभी गरम नहीं हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 313.93, "end": 315.32, "text": "ठंडी चीज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 315.32, "end": 316.58, "text": "कोर नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 316.58, "end": 318.39, "text": "कभी कोर नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 318.84, "end": 325.44, "text": "साठ साल तक, एक परिवार ने धातु के एक बेज़रर टुकड़े की ऐसे रखवाली की,", "who": "", "voice": "narrator", "diary": false}, {"start": 325.44, "end": 328.2, "text": "जैसे वो देवी की अपनी आँख हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 328.2, "end": 339.32, "text": "और सालों तक, एक बहुत चालाक, बहुत अमीर आदमी ने, उस परिवार के गीत का हिमालय के पार पीछा किया, बूढ़ों को धमकाते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 339.32, "end": 344.93, "text": "माँओं को डराते हुए, और एक लड़के को एक पहाड़ पर भेजते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 344.93, "end": 347.98, "text": "जो कभी वापस नहीं आया, इसके लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 348.43, "end": 351.89, "text": "रोहन ने ब्रैकेट उठाया, और उसे अपने हाथों में पलटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 351.89, "end": 355.27, "text": "फिर उसने कुछ ऐसा किया, जिसकी मुझे उम्मीद नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 355.97, "end": 356.61, "text": "वो हँसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 357.31, "end": 358.72, "text": "ज़ोर से नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 358.72, "end": 362.19, "text": "एक छोटी, थकी हुई, चटकी हुई हँसी,", "who": "", "voice": "narrator", "diary": false}, {"start": 362.19, "end": 366.63, "text": "जैसे उसके अंदर, बहुत दूर, कुछ टूट रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 367.08, "end": 368.01, "text": "एक ब्रैकेट।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 368.21, "end": 369.63, "text": "उसने बिना ऊपर देखे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 369.83, "end": 371.54, "text": "एक ब्रैकेट, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 371.99, "end": 375.11, "text": "एक चरवाहे का सबसे क़ीमती ख़ज़ाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 375.31, "end": 376.1, "text": "मैंने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 376.3, "end": 378.06, "text": "आपके लिए एक ब्रैकेट।", "who": "", "voice": "narrator", "diary": false}, {"start": 378.06, "end": 379.9, "text": "उनके लिए नंदा की आँख।", "who": "", "voice": "narrator", "diary": false}, {"start": 380.35, "end": 382.2, "text": "मैंने ये कहने का प्लान नहीं किया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 382.2, "end": 382.82, "text": "बस निकल गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 383.27, "end": 385.19, "text": "पुलिस मेरे पीछे अंदर आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 385.19, "end": 394.85, "text": "एक अफ़सर ने, बहुत औपचारिक ढंग से, रोहन का पूरा नाम लिया, और उसके बाद गिरफ़्तारी, और किडनैपिंग, और आपराधिक धमकी जैसे शब्द,", "who": "", "voice": "narrator", "diary": false}, {"start": 394.85, "end": 401.08, "text": "और क़ानून की धाराओं की एक लंबी लड़ी, जो मुझे समझ नहीं आई, सिवाय एक फ़्रेज़ के,", "who": "", "voice": "narrator", "diary": false}, {"start": 401.08, "end": 406.11, "text": "जिसने आख़िरकार रोहन के चेहरे को बदल दिया: रेडियोएक्टिव मटीरियल।", "who": "", "voice": "narrator", "diary": false}, {"start": 406.56, "end": 410.38, "text": "वो खड़ा हुआ, और अपना लंबा, गहरा कोट झाड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 410.38, "end": 412.28, "text": "उसने विरोध नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 412.28, "end": 416.1, "text": "अब भी, यहाँ भी, वो शराफ़त से पेश आ रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 417.6, "end": 422.76, "text": "जब वो उसे तीन गोल पत्थरों के पास से बाहर ले जा रहे थे, एक अफ़सर,", "who": "", "voice": "narrator", "diary": false}, {"start": 422.76, "end": 425.02, "text": "उस सामान के ढेर के पास रुका,", "who": "", "voice": "narrator", "diary": false}, {"start": 425.02, "end": 429.06, "text": "जो रोहन के आदमियों ने झोपड़ी के बाहर गिरा दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 429.06, "end": 429.54, "text": "रकसैक।", "who": "", "voice": "narrator", "diary": false}, {"start": 429.54, "end": 430.27, "text": "रस्सियाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 430.27, "end": 431.56, "text": "रडार वाली स्लेज।", "who": "", "voice": "narrator", "diary": false}, {"start": 431.56, "end": 433.34, "text": "आइस-एक्सेज़ का एक ढेर।", "who": "", "voice": "narrator", "diary": false}, {"start": 433.79, "end": 437.22, "text": "गौरव बिल्कुल स्थिर खड़ा था, उनमें से एक को देखते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 437.67, "end": 444.06, "text": "वो बाक़ियों से पुरानी थी: लकड़ी के हत्थे वाली एक कुल्हाड़ी, इस्तेमाल से घिसकर चिकनी,", "who": "", "voice": "narrator", "diary": false}, {"start": 444.06, "end": 448.39, "text": "उसका स्टील का सिर, सालों की बर्फ़ से खरोंचा और पिचका हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 448.39, "end": 450.98, "text": "हत्थे पर एक लैमिनेटेड टैग बँधा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 450.98, "end": 454.85, "text": "धूप से फीका: समिट सीक्रेट्स, एक्सपीडिशन इक्विपमेंट।", "who": "", "voice": "narrator", "diary": false}, {"start": 455.3, "end": 459.46, "text": "और सिर के ठीक नीचे, लकड़ी में खुदे हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 459.46, "end": 463.94, "text": "छोटे, सावधान, और थोड़े टेढ़े, दो अक्षर थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 464.64, "end": 464.84, "text": "डी।", "who": "", "voice": "narrator", "diary": false}, {"start": 464.84, "end": 465.04, "text": "आर।", "who": "", "voice": "narrator", "diary": false}, {"start": 465.74, "end": 466.8, "text": "मैंने किया था।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 467.0, "end": 468.13, "text": "गौरव ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 468.13, "end": 470.67, "text": "उसकी आवाज़ बिल्कुल शांत थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 470.87, "end": 472.88, "text": "उसके अठारहवें जन्मदिन पे।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 472.88, "end": 473.52, "text": "चाकू से।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 473.52, "end": 477.05, "text": "उसने मुझे डाँटा था, कि शाफ़्ट ख़राब कर दिया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 477.75, "end": 478.6, "text": "कोई हिला नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 479.3, "end": 483.83, "text": "उसने कुल्हाड़ी उठाई, और आख़िरकार, रोहन की तरफ़ देखने के लिए मुड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 483.83, "end": 487.54, "text": "जो दो अफ़सरों के बीच, बुग्याल के किनारे पर रुक गया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 487.99, "end": 490.75, "text": "कंपनी ने कहा था, दीपक क्रेवास में गिरा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 490.75, "end": 491.81, "text": "बॉडी नहीं मिली।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 491.81, "end": 492.8, "text": "कुछ नहीं मिला।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 492.8, "end": 494.07, "text": "कुछ वापस नहीं आया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 494.27, "end": 495.83, "text": "उसने कुल्हाड़ी ऊपर उठाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 496.03, "end": 497.34, "text": "तो ये कैसे वापस आया?", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 497.79, "end": 500.03, "text": "रोहन देर तक कुल्हाड़ी को देखता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 500.48, "end": 504.41, "text": "फिर उसने एक शांत, लगभग उलझी हुई आवाज़ में कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 504.41, "end": 507.91, "text": "जैसे दो साल बाद भी ये बात उसे चिढ़ाती हो:", "who": "", "voice": "narrator", "diary": false}, {"start": 508.36, "end": 510.88, "text": "वो लड़का, वो गाना बंद ही नहीं करता था।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 511.33, "end": 513.05, "text": "बस इतना ही उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 513.05, "end": 514.08, "text": "वो काफ़ी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 514.08, "end": 517.26, "text": "उसके बग़ल वाले अफ़सर ने उसे लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 517.26, "end": 520.27, "text": "कमांडेंट धामी के दोनों ख़ामोश आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 520.27, "end": 524.75, "text": "बिना किसी हंगामे के, उसके दोनों तरफ़ आकर खड़े हो गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 525.2, "end": 526.84, "text": "गौरव चिल्लाया नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 526.84, "end": 528.48, "text": "उसने उसे मारा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 528.48, "end": 530.38, "text": "वो रोया नहीं, तब नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 530.38, "end": 536.26, "text": "उसने बस अपने भाई की कुल्हाड़ी दोनों हाथों में थामी, बहुत सावधानी से,", "who": "", "voice": "narrator", "diary": false}, {"start": 536.26, "end": 540.67, "text": "उस तरह, जैसे आप मौत से लौटी किसी चीज़ को थामते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 540.67, "end": 543.26, "text": "उसने रोहन सहगल की तरफ़ पीठ की,", "who": "", "voice": "narrator", "diary": false}, {"start": 543.26, "end": 547.15, "text": "और देर तक घाटी के पार नंदा देवी को देखता रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 547.6, "end": 550.05, "text": "मैं जाकर उसके बग़ल में खड़ा हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 550.05, "end": 551.38, "text": "मैंने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 551.38, "end": 554.18, "text": "ऐसा कुछ नहीं था, जो एक प्रोफ़ेसर कह सके।", "who": "", "voice": "narrator", "diary": false}, {"start": 554.63, "end": 558.34, "text": "कुछ देर बाद, गौरव बोला, अब भी पहाड़ को देखते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 558.54, "end": 564.06, "text": "देवता ने कहा था, जो पहाड़ ने लिया है, उसे वापस मत माँगो।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 564.51, "end": 564.88, "text": "हाँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 565.33, "end": 566.39, "text": "मैंने नहीं माँगा।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 566.59, "end": 568.49, "text": "उसने कुल्हाड़ी की तरफ़ नीचे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 568.69, "end": 570.31, "text": "पहाड़ ने ख़ुद भेज दिया।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 571.81, "end": 575.47, "text": "वो सुबह के बीच में रोहन को पहाड़ से नीचे ले गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 575.47, "end": 583.87, "text": "और भल्ला को भी, हथकड़ियों और एक जूते में, जो रात तीन बजकर सोलह मिनट से ख़ामोश आदमियों के साथ बैठा था, और जो,", "who": "", "voice": "narrator", "diary": false}, {"start": 583.87, "end": 590.96, "text": "कमांडेंट धामी ने हमें बाद में बताया, पिथौरागढ़ ज़िले में किसी के भी द्वारा पूछताछ किया गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 590.96, "end": 594.07, "text": "सबसे ज़्यादा सहयोग करने वाला संदिग्ध था।", "who": "", "voice": "narrator", "diary": false}, {"start": 594.52, "end": 595.15, "text": "उसने कहा।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 595.35, "end": 597.01, "text": "कमांडेंट ने मुझे फ़ोन पर बताया,", "who": "", "voice": "narrator", "diary": false}, {"start": 597.21, "end": 601.85, "text": "कि जंगल ने उसे उसकी माँ की आवाज़ में डाँटा।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 601.85, "end": 607.36, "text": "वो सब कुछ बता देगा, बस उसे दोबारा पहाड़ पे मत भेजो।", "who": "कमांडेंट धामी", "voice": "dhami", "diary": false}, {"start": 607.81, "end": 610.0, "text": "क्षितिज स्पीकर पर सुन रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 610.2, "end": 611.81, "text": "टेक्निकली, उसे किसने डाँटा था?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 612.26, "end": 613.06, "text": "मेरी माँ ने।", "who": "", "voice": "narrator", "diary": false}, {"start": 613.26, "end": 614.05, "text": "मैंने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 614.5, "end": 615.68, "text": "तो टेक्निकली वो सही है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 615.88, "end": 618.42, "text": "क्षितिज ने कहा, और उसे लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 618.87, "end": 620.98, "text": "फिर कमांडेंट की आवाज़ बदल गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 620.98, "end": 624.12, "text": "उन्होंने मुझसे फ़ोन स्पीकर से हटाने को कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 624.12, "end": 627.69, "text": "और गौरव को एक तरफ़ ले जाकर, उसे फ़ोन देने को कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 627.69, "end": 629.44, "text": "गौरव ने एक मिनट तक सुना।", "who": "", "voice": "narrator", "diary": false}, {"start": 629.44, "end": 633.16, "text": "फिर उसने बिना एक शब्द कहे फ़ोन मेरी तरफ़ बढ़ा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 633.16, "end": 636.29, "text": "उसने मुझसे रुकने को कहा, क्योंकि, उसने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 636.29, "end": 639.57, "text": "उसे नहीं लगता था, कि वो इसे दो बार सुन पाएगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 640.02, "end": 647.25, "text": "ये वो है, जो भल्ला ने सुबह चार बजे ख़ामोश आदमियों को बताया था, उसके हाथ हथकड़ियों में,", "who": "", "voice": "narrator", "diary": false}, {"start": 647.25, "end": 651.45, "text": "और उसका एक नंगा पैर, उधार की एक शॉल में लिपटा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 651.45, "end": 653.72, "text": "किसी बच्चे की तरह रोते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 654.17, "end": 659.75, "text": "दो साल पहले, पहाड़ पर बहुत ऊपर, उस प्राइवेट एक्सपीडिशन की आख़िरी रात,", "who": "", "voice": "narrator", "diary": false}, {"start": 659.75, "end": 663.15, "text": "दीपक समझ गया था, कि वो ग्रे केस किसलिए था।", "who": "", "voice": "narrator", "diary": false}, {"start": 663.15, "end": 666.31, "text": "उसने रोहन से कहा, कि वो आगे नहीं जाएगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 666.31, "end": 669.54, "text": "उसने कहा, कि वो नीचे जाकर सबको बता देगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 669.54, "end": 671.08, "text": "एक तूफ़ान आ रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 671.08, "end": 672.62, "text": "रोहन चिल्लाया नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 672.62, "end": 674.64, "text": "रोहन कभी बदतमीज़ नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 674.64, "end": 676.66, "text": "उसने बस इतना कहा, ठीक है।", "who": "", "voice": "narrator", "diary": false}, {"start": 676.66, "end": 677.39, "text": "नीचे जाओ।", "who": "", "voice": "narrator", "diary": false}, {"start": 677.39, "end": 683.78, "text": "और उसने दीपक की रस्सी, और दीपक की कुल्हाड़ी, और दीपक का रेडियो, कंपनी का सामान,", "who": "", "voice": "narrator", "diary": false}, {"start": 683.78, "end": 687.17, "text": "अपने पास रख लिया, और उसे ग्लेशियर से नीचे,", "who": "", "voice": "narrator", "diary": false}, {"start": 687.17, "end": 689.93, "text": "अकेले, रात में, मौसम में भेज दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 690.38, "end": 693.06, "text": "भल्ला ने उसके साथ जाने की भीख माँगी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 693.06, "end": 694.44, "text": "रोहन ने मना कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 694.44, "end": 695.81, "text": "भल्ला ने बात मान ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 696.26, "end": 701.94, "text": "पूरी रात, भल्ला ने कहा, उसने नीचे जाते दीपक को गाते सुना: वो पुराना गीत,", "who": "", "voice": "narrator", "diary": false}, {"start": 701.94, "end": 705.81, "text": "उसके दादा का गीत, हवा में धीमा, और धीमा होता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 705.81, "end": 708.65, "text": "और फिर उसे वो सुनाई देना बंद हो गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 709.35, "end": 711.0, "text": "पहाड़ पे अकेले मत जाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 711.7, "end": 715.3, "text": "गौरव ने ये सब बिल्कुल स्थिर खड़े होकर सुना,", "who": "", "voice": "narrator", "diary": false}, {"start": 715.3, "end": 720.0, "text": "अपने भाई की कुल्हाड़ी हाथों में लिए, पहाड़ को देखते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 720.0, "end": 723.69, "text": "जब मैंने ख़त्म किया, उसने एक बार सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 724.14, "end": 725.36, "text": "कमांडेंट साहब को बोलना।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 725.56, "end": 726.44, "text": "उसने मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 726.64, "end": 730.3, "text": "भल्ला को बोलना, मैं उसे माफ़ नहीं कर सकता।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 730.3, "end": 731.08, "text": "अभी नहीं।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 731.28, "end": 732.4, "text": "उसने थूक निगला।", "who": "", "voice": "narrator", "diary": false}, {"start": 732.6, "end": 733.84, "text": "पर उसने सच बोला।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 733.84, "end": 736.24, "text": "दीपक के लिए किसी ने तो सच बोला।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 736.69, "end": 746.09, "text": "ब्रैकेट पुलिस के साथ गया, अपने फीके लाल कपड़े में वापस लिपटा हुआ, एक वादे के साथ, जो इंचार्ज अफ़सर ने गब्बर से किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 746.09, "end": 751.12, "text": "और जिसे गब्बर ने उनसे दो बार दोहरवाया, कि जाँच हो जाने के बाद,", "who": "", "voice": "narrator", "diary": false}, {"start": 751.12, "end": 754.52, "text": "वो कुंदन सिंह के परिवार के पास वापस जाएगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 754.52, "end": 755.65, "text": "जहाँ का वो है।", "who": "", "voice": "narrator", "diary": false}, {"start": 756.1, "end": 759.87, "text": "हम दोपहर की रोशनी में, दूसरों के पीछे-पीछे,", "who": "", "voice": "narrator", "diary": false}, {"start": 759.87, "end": 765.38, "text": "बुराँस के जंगल से नीचे उतरे, बहुत धीरे, लगभग कुछ नहीं कहते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 765.38, "end": 770.81, "text": "मेरी टाँगें, चैप्टर एट के आसपास कहीं, मेरी होना बंद हो गई थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 770.81, "end": 772.91, "text": "मुझे कोई शिकायत नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 774.41, "end": 784.26, "text": "उस शाम, मुनस्यारी के किनारे, एक चाय की दुकान पर, जहाँ से पंचाचूली की चोटियाँ आख़िरी रोशनी में गुलाबी होती दिख रही थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 784.26, "end": 786.85, "text": "घुटने पर ढोल रखे एक बूढ़ा आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 786.85, "end": 789.61, "text": "एक छोटी सी भीड़ के लिए गा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 790.06, "end": 793.89, "text": "गब्बर ने पहली लाइनें सुनीं, और सड़क पर एकदम रुक गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 794.34, "end": 795.62, "text": "राजुला-मालूशाही।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 795.82, "end": 796.93, "text": "उन्होंने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 797.38, "end": 801.71, "text": "तो हम पाँचों, अपनी चाय लेकर, लकड़ी की एक बेंच पर बैठ गए,", "who": "", "voice": "narrator", "diary": false}, {"start": 801.71, "end": 804.95, "text": "और कुमाऊँ की सबसे पुरानी प्रेम कहानी सुनी,", "who": "", "voice": "narrator", "diary": false}, {"start": 804.95, "end": 807.35, "text": "उसी घाटी में, जहाँ से वो आई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 807.8, "end": 810.44, "text": "मैं आपको उसका ढाँचा बताता हूँ, उसी तरह,", "who": "", "voice": "narrator", "diary": false}, {"start": 810.44, "end": 814.22, "text": "जैसे गब्बर ने बूढ़े आदमी के गाते हुए मेरे कान में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 814.22, "end": 817.13, "text": "अलग-अलग गाँव इसे अलग-अलग ढंग से सुनाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 817.13, "end": 818.28, "text": "हमेशा सुनाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 818.73, "end": 824.15, "text": "बहुत पहले, जोहार की ऊँची घाटी में, राजुला नाम की एक लड़की रहती थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 824.15, "end": 828.59, "text": "सुनपति नाम के एक अमीर शौका व्यापारी की बेटी: एक लड़की,", "who": "", "voice": "narrator", "diary": false}, {"start": 828.59, "end": 833.44, "text": "इतनी सुंदर, गीत कहता है, कि उसके आगे सूरज फीका पड़ जाता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 833.44, "end": 835.98, "text": "बहुत दूर दक्षिण में, बैराठ में,", "who": "", "voice": "narrator", "diary": false}, {"start": 835.98, "end": 839.93, "text": "कत्यूरी राजाओं का एक जवान राजकुमार था, मालूशाही।", "who": "", "voice": "narrator", "diary": false}, {"start": 839.93, "end": 841.98, "text": "जब वो दोनों बहुत छोटे थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 841.98, "end": 846.83, "text": "उनके परिवारों ने उन्हें एक-दूसरे को सौंपने का वादा किया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 847.28, "end": 849.64, "text": "फिर परिवारों ने अपना मन बदल लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 849.64, "end": 852.87, "text": "राजुला के पिता ने उसकी शादी कहीं और तय कर दी,", "who": "", "voice": "narrator", "diary": false}, {"start": 852.87, "end": 855.52, "text": "पहाड़ों के पार के एक ताक़तवर आदमी से।", "who": "", "voice": "narrator", "diary": false}, {"start": 855.52, "end": 861.26, "text": "और मालूशाही की माँ ने, जो अपने बेटे के लिए ऊँची घाटियों की लड़की नहीं चाहती थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 861.26, "end": 863.48, "text": "उसे नींद की एक जड़ी-बूटी दे दी,", "who": "", "voice": "narrator", "diary": false}, {"start": 863.48, "end": 866.78, "text": "ताकि जब राजुला उसे ढूँढने आए, तो वो जागे नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 867.48, "end": 869.32, "text": "और राजुला फिर भी आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 870.02, "end": 874.11, "text": "यही वो हिस्सा था, जो बूढ़े आदमी ने सबसे लंबा गाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 874.11, "end": 876.97, "text": "ऊँचे सुरों पर उनकी आवाज़ टूटती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 876.97, "end": 883.92, "text": "जोहार की एक लड़की, अकेली, कुमाऊँ के पहाड़ों को पैदल पार करती हुई, उस लड़के को ढूँढने,", "who": "", "voice": "narrator", "diary": false}, {"start": 883.92, "end": 888.49, "text": "जिसे उसे सौंपने का वादा किया गया था: जंगलों से होते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 888.49, "end": 891.44, "text": "दर्रों के ऊपर से, मंदिरों के पास से।", "who": "", "voice": "narrator", "diary": false}, {"start": 891.44, "end": 894.46, "text": "अपने पिता के ख़िलाफ़ बग़ावत करती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 894.46, "end": 896.83, "text": "एक ताक़तवर रिश्ते के ख़िलाफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 896.83, "end": 901.57, "text": "उस पूरी दुनिया के ख़िलाफ़, जो कहती थी, कि वो नहीं कर सकती।", "who": "", "voice": "narrator", "diary": false}, {"start": 902.02, "end": 905.87, "text": "कुछ कहते हैं, मालूशाही ने उसके लिए अपना राज छोड़ दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 905.87, "end": 909.15, "text": "और उसके पीछे जाने के लिए एक भटकता जोगी बन गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 909.15, "end": 913.14, "text": "कुछ कहते हैं, उसे ज़हर दिया गया, और फिर ज़िंदा किया गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 913.14, "end": 917.84, "text": "कुछ कहते हैं, आख़िर में दोनों एक-दूसरे को मिल गए, और कुछ कहते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 917.84, "end": 919.2, "text": "वो कभी मरे ही नहीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 919.2, "end": 922.4, "text": "कि वो अब भी इन पहाड़ों में कहीं हैं, साथ में।", "who": "", "voice": "narrator", "diary": false}, {"start": 922.85, "end": 926.86, "text": "जब बूढ़े आदमी ने ख़त्म किया, कुछ देर तक किसी ने ताली नहीं बजाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 926.86, "end": 927.75, "text": "फिर सबने बजाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 928.2, "end": 929.94, "text": "शाओनी अपनी आँखें पोंछ रही थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 929.94, "end": 932.28, "text": "और ऐसे दिखा रही थी, जैसे नहीं पोंछ रही।", "who": "", "voice": "narrator", "diary": false}, {"start": 932.73, "end": 933.6, "text": "एक लड़की।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 933.8, "end": 935.36, "text": "उसने किसी ख़ास से नहीं कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 935.56, "end": 937.4, "text": "जो अकेले पहाड़ पार कर गई।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 937.4, "end": 939.68, "text": "क्योंकि उसने डिसाइड कर लिया था।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 940.13, "end": 941.47, "text": "तीलू रौतेली जैसी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 941.67, "end": 942.5, "text": "गब्बर ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 942.95, "end": 943.68, "text": "दीदी जैसी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 943.88, "end": 946.43, "text": "क्षितिज ने, अपनी नोटबुक से नज़र उठाए बिना कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 946.88, "end": 948.87, "text": "शाओनी ने उसकी बाँह पर मारा।", "who": "", "voice": "narrator", "diary": false}, {"start": 948.87, "end": 953.01, "text": "फिर उसने अपना सिर उसके कंधे पर ठीक तीन सेकंड के लिए रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 953.01, "end": 955.59, "text": "जो उनके परिवार में एक भाषण होता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 957.09, "end": 965.49, "text": "मैं उस बेंच पर बैठा रहा, जब मुनस्यारी के ऊपर तारे निकले, और पंचाचूली की चोटियाँ फीकी होकर धूसर हो गईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 965.49, "end": 971.41, "text": "और मैंने दक्षिण-पश्चिम की तरफ़ देखा, जहाँ नंदा देवी अँधेरे में खड़ी थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 971.41, "end": 974.21, "text": "और मैंने हर चीज़ के बारे में सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 974.66, "end": 980.15, "text": "उन्नीस सौ ग्यारह में एक बंद दरवाज़े के पीछे मरी एक औरत के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 980.15, "end": 984.24, "text": "देवप्रयाग में रात में मिलती दो नदियों के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 984.24, "end": 987.77, "text": "एक नहर के बारे में, जिसकी क़ीमत एक बेटा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 987.77, "end": 991.62, "text": "और एक चट्टान के बारे में, जिसने एक बाढ़ रोक दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 991.62, "end": 995.14, "text": "पाँच टुकड़ों में बँटे एक देवता के बारे में,", "who": "", "voice": "narrator", "diary": false}, {"start": 995.14, "end": 999.97, "text": "और एक गाँव के बारे में, जिसने हनुमान को कभी माफ़ नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 999.97, "end": 1006.85, "text": "एक कंकाल झील पर ग्रीक लोगों के बारे में, और देवताओं को जगाने वाले ढोलों के बारे में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1006.85, "end": 1010.62, "text": "और इंसाफ़ माँगती दस हज़ार घंटियों के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 1010.62, "end": 1017.59, "text": "एक ऐसी गुफा के बारे में, जहाँ हर पत्थर एक देवता है, और धुंध में एक सवारी के बारे में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1017.59, "end": 1021.03, "text": "और एक देवी के बारे में, जो जितना माँगा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1021.03, "end": 1023.32, "text": "उससे कम लेने को राज़ी हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1023.32, "end": 1027.99, "text": "जंगल में एक आवाज़ के बारे में, जिसका हमने जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1028.44, "end": 1034.23, "text": "और प्लूटोनियम के एक डब्बे के बारे में, कहीं उस अँधेरे पहाड़ की बर्फ़ में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1034.23, "end": 1037.63, "text": "अब भी गरम, अब भी धँसता हुआ, अब भी खोया हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1038.08, "end": 1039.57, "text": "मैं एक प्रोफ़ेसर हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1039.57, "end": 1041.9, "text": "अपनी पूरी ज़िंदगी, मैंने माना है,", "who": "", "voice": "narrator", "diary": false}, {"start": 1041.9, "end": 1045.57, "text": "कि हर सवाल का एक जवाब होता है, अगर आप ठीक से ढूँढें।", "who": "", "voice": "narrator", "diary": false}, {"start": 1045.57, "end": 1046.49, "text": "साइंस यही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1046.49, "end": 1047.27, "text": "कोड यही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1047.27, "end": 1048.26, "text": "रिसर्च यही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1048.26, "end": 1052.0, "text": "मैं बारह साल से अपने स्टूडेंट्स को यही बताता आया हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1052.7, "end": 1054.38, "text": "पहाड़ ऐसा नहीं सोचते।", "who": "", "voice": "narrator", "diary": false}, {"start": 1055.08, "end": 1058.17, "text": "पहाड़ कुछ सवाल जानबूझकर रख लेते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1058.17, "end": 1059.55, "text": "डिवाइस कहाँ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1059.55, "end": 1062.73, "text": "ग्रीक लोग रूपकुंड में क्या कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1062.73, "end": 1065.57, "text": "सवॉय में ज़हर असल में किसने डाला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1065.57, "end": 1067.38, "text": "ठीक-ठीक क्या होता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 1067.38, "end": 1072.02, "text": "जब रात तीन बजे एक देवता एक किसान के शरीर में उतरता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1072.02, "end": 1075.46, "text": "जंगल क्या है, जब वो आपका नाम पुकारता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1075.91, "end": 1078.05, "text": "और मैं एक आस्तिक हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1078.05, "end": 1083.35, "text": "जिसका मतलब है, कि आख़िरकार मैंने इससे सुलह कर ली है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1083.8, "end": 1087.37, "text": "कुछ सवाल जवाब दिए जाने के लिए नहीं होते।", "who": "", "voice": "narrator", "diary": false}, {"start": 1087.37, "end": 1090.68, "text": "कुछ सँभालकर रखे जाने के लिए होते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1090.68, "end": 1093.36, "text": "आग के पास बैठी एक दादी के पास।", "who": "", "voice": "narrator", "diary": false}, {"start": 1093.36, "end": 1095.86, "text": "एक गीत में एक चरवाहे के पास।", "who": "", "voice": "narrator", "diary": false}, {"start": 1095.86, "end": 1100.59, "text": "लाल कपड़े और लकड़ी के एक डब्बे वाले एक परिवार के पास।", "who": "", "voice": "narrator", "diary": false}, {"start": 1100.59, "end": 1102.02, "text": "एक पहाड़ के पास।", "who": "", "voice": "narrator", "diary": false}, {"start": 1102.47, "end": 1105.11, "text": "यही छुपा हुआ उत्तराखंड है, रीडर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1105.11, "end": 1107.58, "text": "यही देवभूमि का अनकहा रहस्य है।", "who": "", "voice": "narrator", "diary": false}, {"start": 1107.58, "end": 1110.14, "text": "बर्फ़ में दबी कोई एक चीज़ नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1110.14, "end": 1115.83, "text": "हज़ारों चीज़ें, सावधानी से सँभाली हुई, उन लोगों के पास, जो जानते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 1115.83, "end": 1120.79, "text": "कि कुछ कहानियाँ, जवाब बनने से पहले, एक ज़िम्मेदारी होती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 1122.29, "end": 1123.56, "text": "मेरा फ़ोन बज़ हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1124.26, "end": 1124.64, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1125.34, "end": 1126.6, "text": "पकड़ा गया वो आदमी?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 1127.05, "end": 1128.03, "text": "पकड़ा गया, मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1128.48, "end": 1128.96, "text": "अच्छा है।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 1129.16, "end": 1129.96, "text": "एक पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 1130.16, "end": 1130.94, "text": "अब घर आ जाओ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 1130.94, "end": 1132.51, "text": "बहुत हो गया पहाड़-वहाड़।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 1132.96, "end": 1133.45, "text": "आ रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1133.9, "end": 1134.54, "text": "और पार्थ?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 1134.99, "end": 1135.31, "text": "हाँ?", "who": "", "voice": "narrator", "diary": false}, {"start": 1135.76, "end": 1136.4, "text": "स्वेटर…", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 1136.85, "end": 1137.79, "text": "तीन, मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1137.99, "end": 1138.55, "text": "मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1138.75, "end": 1140.19, "text": "हमेशा तीन।", "who": "", "voice": "narrator", "diary": false}, {"start": 1141.69, "end": 1146.39, "text": "दो दिन बाद, गब्बर हमें बसंती में नीचे काठगोदाम ले गए, धीरे-धीरे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1146.39, "end": 1147.79, "text": "खिड़कियाँ खोले हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 1147.79, "end": 1151.1, "text": "और स्टीरियो पर पुराने गढ़वाली गाने चलाते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 1151.1, "end": 1153.89, "text": "गौरव अपनी सफ़ेद एस-यू-वी में पीछे आया,", "who": "", "voice": "narrator", "diary": false}, {"start": 1153.89, "end": 1158.01, "text": "पैसेंजर सीट पर दीपक की कुल्हाड़ी, एक कंबल में लिपटी हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1158.46, "end": 1161.74, "text": "रेलवे स्टेशन पर, गब्बर ने देर तक मुझसे हाथ मिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1162.19, "end": 1164.49, "text": "यहाँ से सीधा इजा के पास।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1164.69, "end": 1165.64, "text": "उन्होंने मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1165.84, "end": 1166.86, "text": "एक हफ़्ता।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1166.86, "end": 1168.18, "text": "फिर हर महीने।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1168.18, "end": 1170.0, "text": "सीज़न हो या ना हो।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1170.45, "end": 1174.77, "text": "वो थोड़े शर्मिंदा दिखे, उस तरह, जैसे उनकी उम्र के आदमी तब दिखते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 1174.77, "end": 1177.57, "text": "जब उन्होंने ज़ोर से कोई फ़ैसला सुना दिया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 1178.02, "end": 1180.26, "text": "उनके सारे गीत रिकॉर्ड करने हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1180.26, "end": 1182.57, "text": "गौरव ने फ़ोन में ऐप डाल दिया है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1182.57, "end": 1184.81, "text": "इस बार सुनूँगा, प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1184.81, "end": 1185.83, "text": "नींद में नहीं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1185.83, "end": 1186.33, "text": "जाग के।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1186.78, "end": 1191.76, "text": "शाओनी, जिसने ऐप, रिकॉर्डिंग का शेड्यूल, और इजा, सॉन्ग्स,", "who": "", "voice": "narrator", "diary": false}, {"start": 1191.76, "end": 1196.21, "text": "फ़ाइनल नाम का एक शेयर्ड फ़ोल्डर ऑर्गनाइज़ किया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 1196.21, "end": 1199.06, "text": "अपने आप से बेहद ख़ुश दिख रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1199.51, "end": 1202.73, "text": "गब्बर अब भी मेरा हाथ पकड़े हुए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1202.93, "end": 1203.98, "text": "प्रोफ़ेसर साहब।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1203.98, "end": 1205.45, "text": "अगली छुट्टी में कहाँ?", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 1205.9, "end": 1207.18, "text": "मैं रीडर की तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1207.18, "end": 1208.9, "text": "मैं अभी आपकी तरफ़ मुड़ रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1209.35, "end": 1210.22, "text": "गब्बर भाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1210.42, "end": 1211.21, "text": "मैंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1211.41, "end": 1212.45, "text": "जहाँ नेटवर्क हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 1212.9, "end": 1214.68, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1214.68, "end": 1217.63, "text": "डे फ़िफ़्टीन, खलिया और मुनस्यारी।", "who": "", "voice": "narrator", "diary": true}, {"start": 1218.08, "end": 1219.02, "text": "ठंडी चीज़,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1219.02, "end": 1224.72, "text": "यानी उन्नीस सौ पैंसठ के सामान का धातु का एक टूटा हुआ ब्रैकेट।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1224.72, "end": 1226.31, "text": "कोई रेडिएशन नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1226.31, "end": 1231.54, "text": "कुंदन सिंह ने उसे तब उठाया, जब वो डब्बे से अब भी गरम था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1231.54, "end": 1234.15, "text": "डब्बा ख़ुद बर्फ़ में रह गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1234.15, "end": 1236.49, "text": "जो गरम था, बर्फ़ ने लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1236.49, "end": 1239.01, "text": "जो ठंडा बचा, चरवाहा ले चला।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1239.01, "end": 1240.79, "text": "गीत, अक्षरशः सच था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1241.24, "end": 1244.81, "text": "नंदा देवी वाला डिवाइस, अब भी खोया हुआ है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1244.81, "end": 1245.86, "text": "आर. ग़लत था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1245.86, "end": 1250.39, "text": "हर वो इंसान सही था, जिसने कहा, कि पहाड़ उसे रखता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1250.84, "end": 1254.72, "text": "दीपक की आइस-एक्स, जिस पर गौरव ने डी. आर. खोदा था,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1254.72, "end": 1257.41, "text": "आर. के एक्सपीडिशन के सामान में थी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1257.41, "end": 1261.37, "text": "आर. ने कहा: वो लड़का, वो गाना बंद ही नहीं करता था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1261.37, "end": 1262.79, "text": "पुलिस ने लिख लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1262.79, "end": 1264.54, "text": "केस फिर से खुल गया है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1264.99, "end": 1268.76, "text": "भल्ला कहता है, जंगल ने उसे उसकी माँ की आवाज़ में डाँटा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1268.76, "end": 1270.96, "text": "वो पार्थ भाई की माँ की आवाज़ थी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1270.96, "end": 1272.4, "text": "टेक्निकली, वो सही है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1272.85, "end": 1275.57, "text": "भल्ला ने दीपक के बारे में सच बताया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1275.57, "end": 1279.23, "text": "आर. ने उसकी रस्सी, कुल्हाड़ी, और रेडियो रख लिए,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1279.23, "end": 1282.18, "text": "और उसे तूफ़ान में अकेले नीचे भेज दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1282.18, "end": 1284.2, "text": "दीपक पूरे रास्ते गाता रहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1284.2, "end": 1286.07, "text": "भल्ला ने उसे रुकते सुना।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1286.07, "end": 1287.31, "text": "माफ़ कर दे, भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1287.31, "end": 1289.03, "text": "गौरव ने कहा, अभी नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1289.03, "end": 1290.81, "text": "मुझे लगता है, अभी नहीं,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1290.81, "end": 1294.23, "text": "इस ट्रिप पर किसी की कही सबसे ईमानदार बात है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1294.68, "end": 1297.25, "text": "राजुला-मालूशाही: जोहार की एक लड़की,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1297.25, "end": 1301.21, "text": "जिसने अकेले पहाड़ पार किए, क्योंकि उसने तय कर लिया था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1301.21, "end": 1301.95, "text": "दीदी रोईं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1301.95, "end": 1306.05, "text": "फिर उन्होंने तीन सेकंड के लिए अपना सिर मेरे कंधे पर रखा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1306.05, "end": 1309.21, "text": "मैं इसे लिख रहा हूँ, ताकि वो मना न कर सकें।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1309.66, "end": 1311.79, "text": "कुछ सवाल पहाड़ रख लेते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1311.79, "end": 1314.79, "text": "पार्थ भाई कहते हैं, ये नाकामी नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1314.79, "end": 1315.74, "text": "यही जवाब है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1316.19, "end": 1319.94, "text": "पुरानी डायरी अब पुलिस के एक एविडेंस बैग में है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1319.94, "end": 1321.7, "text": "नई वाली भी लगभग ख़त्म।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1321.7, "end": 1323.06, "text": "दो पन्ने बचे हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1323.06, "end": 1324.98, "text": "उन्हें बचाकर रख रहा हूँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 18.56, "bed": "chase"}, {"at": 65.11, "bed": "summit"}, {"at": 105.0, "bed": "caper"}, {"at": 123.62, "bed": "suspense"}, {"at": 157.27, "bed": "discovery"}, {"at": 197.06, "bed": "stillness"}, {"at": 214.34, "bed": "legend"}, {"at": 317.64, "bed": "bench"}, {"at": 382.07, "bed": "police"}, {"at": 416.4, "bed": "suspicion"}, {"at": 478.1, "bed": "threat"}, {"at": 510.13, "bed": "sinking"}, {"at": 546.4, "bed": "tender"}, {"at": 570.61, "bed": "caper"}, {"at": 617.67, "bed": "cold"}, {"at": 652.97, "bed": "storm"}, {"at": 708.15, "bed": "stillness"}, {"at": 710.5, "bed": "tender"}, {"at": 754.9, "bed": "trek"}, {"at": 773.21, "bed": "rajula"}, {"at": 806.6, "bed": "legend"}, {"at": 868.82, "bed": "heroic"}, {"at": 900.82, "bed": "rajula"}, {"at": 927.0, "bed": "tender"}, {"at": 955.89, "bed": "stars"}, {"at": 1027.24, "bed": "cold"}, {"at": 1036.88, "bed": "summit"}, {"at": 1121.09, "bed": "caper"}, {"at": 1140.49, "bed": "farewell"}, {"at": 1211.7, "bed": "diary"}, {"at": 1211.7, "bed": "diary"}], "hits": [{"at": 126.65, "fx": "creak"}, {"at": 198.11, "fx": "silence"}, {"at": 215.39, "fx": "flute"}, {"at": 464.49, "fx": "sting"}, {"at": 508.21, "fx": "sting"}, {"at": 565.18, "fx": "bell"}, {"at": 594.37, "fx": "phonering"}, {"at": 696.11, "fx": "flute"}, {"at": 867.33, "fx": "drumhit"}, {"at": 1102.32, "fx": "bell"}, {"at": 1122.14, "fx": "ping"}, {"at": 1141.54, "fx": "carstart"}, {"at": 1209.2, "fx": "sting_light"}, {"at": 1250.69, "fx": "sting_light"}, {"at": 1309.51, "fx": "sting"}], "next": {"label": "एपिलॉग", "en": "Epilogue: Ten Months Later", "hook": "दस महीने बाद। एक मुक़दमा, एक नया चैनल, और एक नोटबुक के आख़िरी पन्ने पर एक नई लाइन।"}};
